package in.finseq.insurance;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class MandatesActivity extends FinseqActivity{
 LinearLayout list;Button sync;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=Ui.column(this);Ui.appHeader(root,this,"NSE Mandates");LinearLayout body=Ui.contentColumn(this);root.addView(body);sync=Ui.greenButton(this,"Bulk Sync Mandates from NSE");body.addView(sync);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);sync.setOnClickListener(new View.OnClickListener(){public void onClick(View v){sync();}});setContentView(Ui.scroll(this,root));load();}
 void load(){Ui.run(this,new Runnable(){public void run(){try{final JSONArray rows=ApiClient.get(MandatesActivity.this,"/api/v2/mf/mandates").optJSONArray("mandates");Ui.ui(MandatesActivity.this,new Runnable(){public void run(){render(rows);}});}catch(final Exception error){Ui.ui(MandatesActivity.this,new Runnable(){public void run(){Ui.toast(MandatesActivity.this,error.getMessage());}});}}});}
 void sync(){sync.setEnabled(false);Ui.run(this,new Runnable(){public void run(){try{final JSONObject response=ApiClient.post(MandatesActivity.this,"/api/v2/mf/mandates/sync",new JSONObject());Ui.ui(MandatesActivity.this,new Runnable(){public void run(){sync.setEnabled(true);JSONArray errors=response.optJSONArray("errors");Ui.toast(MandatesActivity.this,response.optInt("fetched")+" UCC synced · "+response.optInt("mandates")+" mandates · "+response.optInt("failed")+" failed"+(errors!=null&&errors.length()>0?" · "+errors.optString(0):""));load();}});}catch(final Exception error){Ui.ui(MandatesActivity.this,new Runnable(){public void run(){sync.setEnabled(true);Ui.toast(MandatesActivity.this,error.getMessage());}});}}});}
 void render(JSONArray rows){list.removeAllViews();if(rows==null||rows.length()==0){list.addView(Ui.sub(this,"No mandate records synced. Tap Bulk Sync."));return;}list.addView(Ui.sub(this,rows.length()+" mandate record(s)"));for(int i=0;i<Math.min(rows.length(),500);i++){JSONObject record=rows.optJSONObject(i);if(record==null)continue;final JSONObject fields=record.optJSONObject("fields");if(fields==null)continue;LinearLayout card=Ui.card(this);final String id=fields.optString("mandate_id",fields.optString("member_mandate_id","Mandate"));card.addView(Ui.text(this,id,17,true));card.addView(Ui.sub(this,record.optString("name")+" · "+record.optString("ucc")));card.addView(Ui.sub(this,"Status: "+fields.optString("mandate_status",fields.optString("status","—"))));card.addView(Ui.sub(this,"Synced: "+record.optString("fetched_at")));card.setOnClickListener(new View.OnClickListener(){public void onClick(View v){new AlertDialog.Builder(MandatesActivity.this).setTitle("Mandate · "+id).setMessage(fields.toString()).setPositiveButton("Close",null).show();}});list.addView(card);}}
}
